# Exact nonzero cells from the test grid
for r,c,v in [(2,6,3),(3,5,3),(3,6,8),(3,7,3),(4,6,3),(3,13,3),(4,12,3),(4,13,4),(4,14,3),(5,13,3),(9,8,3),(10,7,3),(10,9,3),(11,8,3),(11,14,3),(12,13,3),(12,14,1),(12,15,3),(13,3,3),(13,14,3),(14,2,3),(14,3,2),(14,4,3),(15,3,3)]: a[r][c]=v
assert len(a)==19 and all(len(x)==19 for x in a)
rows={3:8,4:4,12:1,14:2}; cols={6:8,13:4,14:1,3:2}
out=[]
for i in range(19):
 row=[]
 for j in range(19):
  v=a[i][j]
  if v: row.append(v)
