 out.append(row)
import json
print(json.dumps({'action':'submit','grid':out},separators=(',',':')))

a=[[0]*19 for _ in range(19)]
for r,c,v in [(2,6,3),(3,5,3),(3,6,8),(3,7,3),(4,6,3),(3,13,3),(4,12,3),(4,13,4),(4,14,3),(5,13,3),(9,8,3),(10,7,3),(10,9,3),(11,8,3),(11,14,3),(12,13,3),(12,14,1),(12,15,3),(13,3,3),(13,14,3),(14,2,3),(14,3,2),(14,4,3),(15,3,3)]: a[r][c]=v
assert len(a)==19 and all(len(x)==19 for x in a)
centers=[(r,c,a[r][c]) for r in range(19) for c in range(19) if a[r][c] not in (0,3)]
out=[row[:] for row in a]
# For each cross center, extend each cardinal ray. The adjacent 3 is its own arm;
# continue past it, then stop at the next original non-background cell.
for r,c,color in centers:
 for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)):
  rr,cc=r+dr,c+dc
  passed_arm=False
  while 0<=rr<19 and 0<=cc<19:
   if a[rr][cc]!=0:
    if a[rr][cc]==3 and not passed_arm:
     passed_arm=True
     rr+=dr;cc+=dc;continue
    break
   out[rr][cc]=color
   rr+=dr;cc+=dc
# resolve line crossings: vertical ray colors dominate horizontal (matches demos)
# recompute a priority map, retaining original nonzero cells
priority=[[0]*19 for _ in range(19)]
for r,c,color in centers:
 for dr,dc,p in ((-1,0,2),(1,0,2),(0,-1,1),(0,1,1)):
  rr,cc=r+dr,c+dc;passed=False
  while 0<=rr<19 and 0<=cc<19:
   if a[rr][cc]!=0:
    if a[rr][cc]==3 and not passed: passed=True;rr+=dr;cc+=dc;continue
    break
   if p>=priority[rr][cc]: out[rr][cc]=color;priority[rr][cc]=p
   rr+=dr;cc+=dc
import json
print(json.dumps({'action':'submit','grid':out},separators=(',',':')))
